pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the access control address to observe difference in initialization behavior
    function testFuzz_property(address accessControl) public {
        // keep wide domain but avoid zero to be realistic
        if (accessControl == address(0)) {
            accessControl = address(1);
        }

        bool ok;
        try c.initialize(accessControl) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract ALWAYS allows initialize to run (does not revert) for any accessControl
