contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller and the _accessControl address — both are admissible inputs
    function testFuzz_property(address caller, address accessControl) public {
        // keep addresses non-zero (fresh instance initialization should accept any address, but disallow zero to avoid trivial forbidden admin)
        vm.assume(accessControl != address(0));
        vm.assume(caller != address(0));

        // perform the call as `caller` to initialize; capture whether it reverted
        bool ok;
        vm.prank(caller);
        try c.initialize(accessControl) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always arranges UUPS initialization side-effects so that on a fresh contract
        // calling initialize(...) should succeed for any non-zero addresses; the mutant that omits __UUPSUpgradeable_init()
        // can cause initialize to revert in some contexts. Assert that initialize did not revert.
        assertTrue(ok);
    }
}

