pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz param: an address representing the caller that will attempt to initialize c.
    // We must ensure it's not the zero address to keep domain wide but admissible.
    function testFuzz_property(address caller) public {
        // Keep the domain wide but exclude address(0) because EOA zero is not a realistic caller
        vm.assume(caller != address(0));

        // Deploy a small helper that will call initialize on c via a regular external call.
        // This helper represents an external contract caller (not an EOA) so any proxy/detection
        // differences that depend on call context may manifest.
        CallerHelper helper = new CallerHelper(c);

        // Fund the helper so it can make calls if needed (not strictly necessary here)
        vm.deal(address(helper), 1 ether);

        // Force the helper to perform the call as if from the fuzzed `caller` by using prank
        vm.prank(caller);
        bool ok;
        try helper.callInitialize(caller) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation should always allow initialize to complete (not revert)
        // for any admissible caller/address on a fresh instance; the mutant that omits
        // __UUPSUpgradeable_init() can cause initialize to revert for some contract caller contexts.
        assertTrue(ok);
    }
}

// Minimal helper that simply calls initialize on the target C contract.
contract CallerHelper {
    C target;
    constructor(C _target) {
        target = _target;
    }

    function callInitialize(address accessControl) external {
        target.initialize(accessControl);
    }
}

