pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed param is an address that will act as the caller (we will deploy a helper that performs a delegatecall)
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be meaningful
        vm.assume(caller != address(0));

        // Deploy a minimal proxy-like attacker that will call initialize via delegatecall
        DelegateCaller d = new DelegateCaller(address(c));

        // fund the delegate caller so it can perform calls if needed
        vm.deal(address(d), 1 ether);

        // drive initialize through the helper which does a delegatecall into c
        // If the implementation's initializer relies on UUPS init side-effects, calling via delegatecall
        // (so that address(this).code.length == 0 in the initializer context) can revert on mutant.
        bool ok;
        try d.callInitialize{value: 0}(address(this), address(0)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always completes initialize successfully when invoked via delegatecall helper on a fresh implementation.
        // The mutant that omits __UUPSUpgradeable_init() will revert for some caller contexts; thus we assert success here.
        assertTrue(ok);
    }
}

// Helper that performs a delegatecall into the implementation's initialize
contract DelegateCaller {
    address impl;
    constructor(address _impl) { impl = _impl; }

    // call initialize on impl using delegatecall so that address(this).code.length == 0 inside impl's initializer
    function callInitialize(address caller, address accessControl) external payable {
        // build calldata for initialize(address)
        (bool success, ) = impl.delegatecall(abi.encodeWithSelector(bytes4(keccak256("initialize(address)")), accessControl));
        require(success, "delegatecall init failed");
    }
}

