// Minimal adversarial helper: performs delegatecall into the target's initialize
contract DelegateCaller {
    address impl;
    constructor(address _impl) { impl = _impl; }

    function callInitialize(address _accessControl) external returns (bytes memory) {
        (bool success, bytes memory ret) = impl.delegatecall(
            abi.encodeWithSelector(bytes4(keccak256("initialize(address)")), _accessControl)
