pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter: an arbitrary address used as the access control admin passed to initialize
    function testFuzz_property(address admin) public {
        // Keep admin wide but non-zero (constructor may accept zero, but to be safe allow zero too)
        // We allow admin == address(0) as admissible; do not restrict.

        // Call initialize through an external account (fuzzer chooses admin as argument)
        bool ok;
        try c.initialize(admin) {
            ok = true;
        } catch {
            // If initialize reverts, treat as failure to initialize
            ok = false;
        }

        // The reference contract always marks initialized version to 1 after a successful initialize call.
        // We assert: if initialize returned successfully (ok == true) then the internal initialized version equals 1.
        // We observe this through calling the public helper proxiableUUID? No direct getter exists for Initializable.
        // But Initializable exposes _getInitializedVersion as internal; not public. However, UUPSUpgradeable emits Initialized event
        // and Initializable exposes initializer behavior only via revert on double init. To observe initialized state in public API,
        // we rely on calling initialize again: for the reference, a second call to initialize should revert (InvalidInitialization);
        // for the mutant that didn't set _initialized it will allow second initialize to succeed. Thus we attempt a second initialize
        // and assert that it reverts (i.e., cannot be called twice). We implement this by catching the second call.

        bool secondCallReverted;
        try c.initialize(admin) {
            // second call succeeded
            secondCallReverted = false;
        } catch {
            // expected revert for reference implementation
            secondCallReverted = true;
        }

        // The universal property: For any admin, after a successful first initialize(), a second initialize() call must revert.
        // The mutant that fails to set _initialized to 1 will allow the second call to succeed for some inputs, breaking this.
        // We assert that if the first initialize succeeded then the second call reverted.
        assertTrue(!ok || secondCallReverted);
    }
}

