pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz over an admin address to pass into initialize; the rule: after a successful initialize,
    // calling initialize again must revert on the correct contract (since initialized version == 1),
    // but the mutant (which doesn't set _initialized) will allow the second initialize to succeed.
    function testFuzz_property(address admin) public {
        // keep admin wide but avoid zero address to be realistic
        vm.assume(admin != address(0));

        bool firstOk;
        // First initialize should succeed for both reference and mutant
        try c.initialize(admin) {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        // require that first initialization succeeded (if it reverts for some reason, skip this input)
        // this keeps the admissible domain wide but only checks meaningful cases
        if (!firstOk) return;

        // Now attempt a second initialize call from same admin; on the correct contract this MUST revert
        // (initializer shouldn't allow re-entry). The mutant that didn't set _initialized will succeed.
        bool secondOk;
        try c.initialize(admin) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // SINGLE assertion: the correct contract guarantees the second initialize call reverts
        // so secondOk must be false for the reference; the mutant will have secondOk == true for some input
        assertTrue(!secondOk);
    }
}

