pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: arbitrary access control address
    function testFuzz_property(address accessControl) public {
        // keep wide domain but avoid zero address to be realistic admin
        // Allow zero as well; no tight constraints needed
        // Call initialize as external caller
        bool ok;
        try c.initialize(accessControl) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for any accessControl, the reference contract's initialize either succeeds
        // and afterwards proxiableUUID() (a non-delegated call) returns the well-known slot, or initialize reverts;
        // in all admissible cases the call to proxiableUUID() when called directly must return the implementation slot
        // if callable — we therefore assert that if initialize returned (ok == true) then calling proxiableUUID() succeeds
        // and returns the ERC1967 implementation slot bytes32(0x3608...2bbc).

        if (ok) {
            // proxiableUUID is external view notDelegated; calling it directly should return the constant
            bytes32 slot;
            try c.proxiableUUID() returns (bytes32 s) {
                slot = s;
            } catch {
                // If revert, make test fail: reference should not revert here for any accessControl
                assertTrue(false);
                return;
            }

            // compare against the known ERC1967 slot constant
            // Hardcode the expected slot value from ERC1967Utils.IMPLEMENTATION_SLOT
            bytes32 expected = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
            assertTrue(slot == expected);
        } else {
            // initialize reverted; in that case we cannot further require proxiableUUID; just pass
            assertTrue(true);
        }
    }
}

