pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IVaultTest {
    function currentUtilizationIndex(address _asset) external view returns (uint256);
    function utilization(address _asset) external view returns (uint256);
    function currentUtilizationIndex_set(uint256 v) external;
    function utilization_set(uint256 v) external;
}

// A minimal fake Vault to control returned index and utilization
contract FakeVault is IVaultTest {
    uint256 public idx;
    uint256 public util;
    function currentUtilizationIndex(address) external view returns (uint256) { return idx; }
    function utilization(address) external view returns (uint256) { return util; }
    function currentUtilizationIndex_set(uint256 v) external { idx = v; }
    function utilization_set(uint256 v) external { util = v; }
}

contract InvMutTest is Test {
    C c;
    FakeVault v;

    function setUp() public {
        c = new C();
        v = new FakeVault();
    }

    // Fuzz parameters: priorIndexDiff and elapsedDelta and slopes/kink/etc are not directly settable here,
    // but we can exercise the key deciding values: the vault's returned index and the stored lastUpdate offset.
    // We'll fuzz indexIncrement and lastUpdateOffset and an asset address.
    function testFuzz_property(uint256 indexIncrement, uint256 lastUpdateOffset, address asset) public {
        // Keep values in reasonable ranges but wide: elapsed must be >0 and less than block.timestamp to enter branch.
        // We use vm.warp to set block.timestamp to a known value.
        vm.assume(indexIncrement > 0);
        // cap to avoid overflow in arithmetic in contract
        indexIncrement = bound(indexIncrement, 1, type(uint256).max / 4);
        lastUpdateOffset = bound(lastUpdateOffset, 1, 1 days);

        // Prepare fake vault: current index will be prevIndex + indexIncrement
        uint256 prevIndex = 1e24; // arbitrary previous stored index in adapter storage
        uint256 currentIndex = prevIndex + indexIncrement;
        v.currentUtilizationIndex_set(currentIndex);
        // make utilization fallback value distinct
        v.utilization_set(123456);

        // Set up adapter storage so that utilizationData.index == prevIndex and lastUpdate is block.timestamp - lastUpdateOffset
        // We cannot access internal storage directly, so we will first call rate once to initialize storage with defaults,
        // then modify the storage by simulating a prior run: call rate to set index/lastUpdate to current block.timestamp,
        // then manually write the stored index and lastUpdate by calling rate after warping backwards is impossible.
        // Instead, we will simulate by making utilizationData.lastUpdate be block.timestamp - lastUpdateOffset by first
        // warping to an earlier time and calling a no-op to set storage, then warping forward.

        // Step A: set a base time
        uint256 base = 1_000_000;
        vm.warp(base);

        // Call rate once so that storage gets some initialization with lastUpdate == base
        // For this call, make fake vault return currentIndex == prevIndex (so utilization branch uses IVault.utilization)
        v.currentUtilizationIndex_set(prevIndex);
        c.initialize(address(this)); // need to initialize access; Access.checkAccess won't be used for rate
        // call rate to initialize storage for this vault/asset
        c.rate(address(v), asset);

        // Now simulate that stored utilizationData.index == prevIndex and lastUpdate == base
        // We'll warp forward by lastUpdateOffset to produce elapsed = lastUpdateOffset
        vm.warp(base + lastUpdateOffset);

        // Now set the vault to return the increased index so that (index - prevIndex) == indexIncrement
        v.currentUtilizationIndex_set(currentIndex);

        // Now call rate and capture the returned latestAnswer using try/catch to observe behaviour
        bool okRef;
        uint256 ansRef;
        // Call reference contract's rate (this file is compiled against reference C). We expect reference should not revert.
        try c.rate(address(v), asset) returns (uint256 a) {
            okRef = true;
            ansRef = a;
        } catch {
            okRef = false;
            ansRef = 0;
        }

        // The general rule: reference never reverts for these admissible inputs and produces a deterministic latestAnswer
        // We assert that the call succeeded (did not revert). This must hold for the reference for all admissible inputs.
        assertTrue(okRef);

        // Note: The mutant (pre-scaling) will for some choices of indexIncrement and lastUpdateOffset produce a different
        // returned latestAnswer because integer division ordering differs when indexIncrement not divisible by elapsed.
        // Our single assert is the universal property the reference satisfies: the call does not revert.
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IVaultMinimal {
    function currentUtilizationIndex(address _asset) external returns (uint256);
    function utilization(address _asset) external view returns (uint256);
    function currentUtilizationIndex_noop(address _asset) external returns (uint256);
    function currentUtilizationIndex_set(uint256 v) external;
}

// Minimal vault mock that allows controlling currentUtilizationIndex and utilization
contract VaultMock {
    uint256 public idx;
    uint256 public util;
    constructor() {
        idx = 0;
        util = 0;
    }
    function setIndex(uint256 v) external { idx = v; }
    function setUtil(uint256 v) external { util = v; }
    function currentUtilizationIndex(address) external returns (uint256) { return idx; }
    function utilization(address) external view returns (uint256) { return util; }
    // helpers for direct calls if needed by fuzzer (not used)
    function currentUtilizationIndex_noop(address) external returns (uint256) { return idx; }
    function currentUtilizationIndex_set(uint256 v) external { idx = v; }
}

contract InvMutTest is Test {
    C c;
    VaultMock vault;

    function setUp() public {
        c = new C();
        vault = new VaultMock();
    }

    // Fuzz parameters:
    // - prevIndex: previous stored utilization index in adapter storage (we simulate by first calling rate to set storage)
    // - newIndex: value returned by vault.currentUtilizationIndex (the changed index)
    // - elapsedWarp: how much to advance block.timestamp so elapsed = warp - lastUpdate is this (must be >0 and not equal to warp to avoid construction branch)
    // We will use fuzzing to find a case where (newIndex - prevIndex) not divisible by elapsed, causing mutant to differ.
    function testFuzz_property(uint256 prevIndex, uint256 newIndex, uint256 elapsedWarp) public {
        // Keep elapsed in a reasonable non-zero range and avoid extremely large warps
        uint256 elapsed = bound(elapsedWarp, 1, 1 days);

        // Choose an asset address to pass (any non-zero)
        address asset = address(0xABCD);

        // Prepare vault: set its index to prevIndex and utilization to some fallback value
        vault.setIndex(prevIndex);
        vault.setUtil(123); // arbitrary

        // Initialize adapter storage by calling rate once so it records utilizationData.index = prevIndex and lastUpdate = block.timestamp
        // First, ensure c is initialized so rate can be called: need to call initialize with some accessControl address.
        // Use an arbitrary non-zero address as access control; Access.checkAccess isn't invoked for rate.
        c.initialize(address(1));

        // call rate once to set initial index/lastUpdate
        c.rate(address(vault), asset);

        // Advance vault's index to newIndex
        vault.setIndex(newIndex);

        // Warp forward by `elapsed` seconds so that block.timestamp > lastUpdate and elapsed computed inside matches our elapsed
        vm.warp(block.timestamp + elapsed);

        // Now call rate and capture the returned latestAnswer from the reference implementation.
        // We use try/catch to convert potential reverts to boolean, but here we want the returned value.

        uint256 refAnswer;
        bool refOk;
        try c.rate(address(vault), asset) returns (uint256 v) {
            refAnswer = v;
            refOk = true;
        } catch {
            // If reference reverts, this input is inadmissible for our property; skip by assuming false condition
            // Use vm.assume to discard this fuzz input
            vm.assume(false);
